<script setup lang="ts">
import {onHide as onPageHide} from "@dcloudio/uni-app"
import {abandonLogin as cancelPageLogin} from "../../features/auth"
onPageHide(cancelPageLogin)

import LoginSheet from "../../components/LoginSheet.vue"

import { ref } from 'vue';import { onLoad,onShow } from '@dcloudio/uni-app';import { request,navigate,token,type Row } from '../../api/platform'
const editId=ref('')
const editing=ref<Row|null>(null),quietStart=ref(''),quietEnd=ref(''),signedIn=ref(false)
const rules=ref<Row[]>([]),deliveries=ref<Row[]>([]),status=ref<Row|null>(null),targetId=ref(''),targetType=ref('ARTICLE'),mode=ref('INSTANT'),channel=ref('WECHAT_SUBSCRIBE'),date=ref(''),time=ref('09:00'),error=ref(''),busy=ref(false)
async function load(){signedIn.value=!!token();if(!signedIn.value){rules.value=[];deliveries.value=[];status.value=null;return}[rules.value,deliveries.value,status.value]=await Promise.all([request('GET','/api/v1/me/notifications/rules'),request('GET','/api/v1/me/notifications/deliveries'),request('GET','/api/v1/me/notifications/status')])}
function body(r:Row){return {targetType:r.targetType,targetId:r.targetId,mode:r.mode,channel:r.channel,timezone:r.timezone||'Asia/Shanghai',scheduledAt:r.scheduledAt||null,localSendTime:r.localSendTime||null,quietStart:r.quietStart||null,quietEnd:r.quietEnd||null,enabled:!!r.enabled,expectedVersion:r.lockVersion||0}}
function edit(r:Row){editing.value=r;targetId.value=r.targetId;targetType.value=r.targetType;mode.value=r.mode;channel.value=r.channel;quietStart.value=r.quietStart?.slice(0,5)||'';quietEnd.value=r.quietEnd?.slice(0,5)||'';time.value=r.localSendTime?.slice(0,5)||'09:00';if(r.scheduledAt){const d=new Date(r.scheduledAt);date.value=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');time.value=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}}
async function toggle(r:Row){if(busy.value)return;busy.value=true;error.value='';try{await request('PUT','/api/v1/me/notifications/rules/'+r.id,{...body(r),enabled:!r.enabled});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request(editing.value?'PUT':'POST','/api/v1/me/notifications/rules'+(editing.value?'/'+editing.value.id:''),{targetType:targetType.value,targetId:targetId.value,mode:mode.value,channel:channel.value,timezone:editing.value?.timezone||'Asia/Shanghai',scheduledAt:mode.value==='AT_TIME'&&date.value?new Date(date.value+'T'+time.value+':00').toISOString():null,localSendTime:mode.value==='DAILY'?time.value+':00':null,quietStart:quietStart.value?quietStart.value+':00':null,quietEnd:quietEnd.value?quietEnd.value+':00':null,enabled:editing.value?!!editing.value.enabled:true,expectedVersion:editing.value?.lockVersion||0});await load();editing.value=null;targetId.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function cancel(id:string){if(busy.value)return;busy.value=true;error.value='';try{await request('DELETE','/api/v1/me/notifications/rules/'+id);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onLoad(q=>{editId.value=String(q?.id||'');targetId.value=String(q?.articleId||q?.targetId||'');targetType.value=String(q?.targetType||'ARTICLE')})
onShow(async()=>{error.value='';try{await load();if(editId.value){const r=rules.value.find(r=>r.id===editId.value);if(r)edit(r);else error.value='提醒不存在'}}catch(e){error.value=(e as Error).message}})
</script><template><view class="page"><view class="hero"><text class="title">兼容日程提醒</text></view><text class="muted">此处保留原有按规则发送的日程提醒；新建变更跟踪请使用强提醒入口。</text><button role="button" class="quiet" @click="navigate('notifications')">返回强提醒</button><text class="error">{{ error }}</text><view v-for="r in rules" :key="r.id" class="card"><text>{{ r.mode }} · {{ r.targetId }}</text><view class="actions"><button role="button" :disabled="busy" :aria-disabled="busy" @click="edit(r)">编辑旧规则</button><button role="button" :disabled="busy" :aria-disabled="busy" @click="toggle(r)">{{ r.enabled?'暂停旧规则':'恢复旧规则' }}</button><button role="button" class="danger" :disabled="busy" :aria-disabled="busy" @click="cancel(r.id)">取消旧规则</button></view></view><button role="button" v-if="!signedIn" @click="navigate('login')">登录</button><view v-if="signedIn&&!targetId" class="card"><text>从资讯或关键词选择提醒对象</text><view class="actions"><button role="button" @click="navigate('search')">选择资讯</button><button role="button" class="quiet" @click="navigate('follows')">我的关注</button></view></view><view v-if="signedIn&&targetId" class="card"><text class="card-title">{{ editing?'编辑提醒':'创建提醒' }}</text><view class="field"><text class="field-label">提醒方式</text><picker :range="['即时更新','具体时间','每日摘要']" @change="mode=['INSTANT','AT_TIME','DAILY'][Number($event.detail.value)]"><view class="picker">{{ ({INSTANT:'即时更新',AT_TIME:'具体时间',DAILY:'每日摘要'} as Row)[mode] }}</view></picker></view><view class="field"><text class="field-label">通道</text><picker :range="['微信订阅消息','企业微信']" @change="channel=['WECHAT_SUBSCRIBE','WECom'][Number($event.detail.value)]"><view class="picker">{{ ({WECHAT_SUBSCRIBE:'微信订阅消息',WECom:'企业微信'} as Row)[channel] }}</view></picker></view><picker v-if="mode==='AT_TIME'" mode="date" @change="date=$event.detail.value"><view class="picker">{{ date||'选择日期' }}</view></picker><picker v-if="mode!=='INSTANT'" mode="time" @change="time=$event.detail.value"><view class="picker">{{ time }}</view></picker><view class="field"><text class="field-label">静默时段（选填，需要同时设置起止）</text><picker mode="time" @change="quietStart=$event.detail.value"><view class="picker">{{ quietStart||'静默开始' }}</view></picker><picker mode="time" @change="quietEnd=$event.detail.value"><view class="picker">{{ quietEnd||'静默结束' }}</view></picker><button role="button" class="quiet" @click="quietStart='';quietEnd=''">清除静默时段</button></view><view class="actions"><button role="button" :disabled="busy" @click="save">{{ editing?'保存修改':'保存提醒' }}</button><button role="button" v-if="editing" class="quiet" @click="editing=null">退出编辑</button></view></view><LoginSheet/></view></template>
